/**
 * Regression tests for the stale-worktree sweep hook (#1884, narrowed #3353).
 *
 * The hook removes orphan `.worktrees/<name>/` shells and stale
 * `.claude/state/worktree-pending/*.json` markers that:
 *   - are NOT in `git worktree list` (fail-closed when git cannot answer)
 *   - contain zero regular files
 *   - have mtime >1 hour old (race protection)
 *
 * It no longer scans sibling `<repo>-*` directories (#3319 retired that
 * layout); a test below pins that a stale sibling survives.
 */

import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import {
  mkdtempSync,
  mkdirSync,
  writeFileSync,
  rmSync,
  existsSync,
  utimesSync,
} from 'node:fs';
import { execFileSync } from 'node:child_process';
import { tmpdir } from 'node:os';
import { join } from 'node:path';

import {
  sweepStaleWorktrees,
  __internals,
} from '../../lifecycle/sweep-stale-worktrees.js';
import { NOOP_CTX } from '../../lib/context.js';

const {
  isEmptyOfFiles,
  sweepWorktreeShells,
  sweepPendingMarkers,
  MIN_AGE_MS,
} = __internals;

// Set the path mtime to N ms in the past (helper to bypass the 1h race guard).
function backdate(path: string, msAgo: number): void {
  const t = (Date.now() - msAgo) / 1000;
  utimesSync(path, t, t);
}

describe('sweepStaleWorktrees (#1884)', () => {
  let parent: string;
  let project: string;
  let originalProject: string | undefined;

  beforeEach(() => {
    // tmp parent dir holds the fake "project" and its siblings.
    parent = mkdtempSync(join(tmpdir(), 'sweep-stale-parent-'));
    project = join(parent, 'fakerepo');
    mkdirSync(project, { recursive: true });
    // Initialize the project as a real git repo so `git worktree list` succeeds
    // and returns an empty registry (rather than failing → null → bail out
    // under the new fail-closed registry-check behavior).
    execFileSync('git', ['init', '--quiet', project], { stdio: 'ignore' });
    originalProject = process.env.CLAUDE_PROJECT_DIR;
    process.env.CLAUDE_PROJECT_DIR = project;
  });

  afterEach(() => {
    if (originalProject === undefined) delete process.env.CLAUDE_PROJECT_DIR;
    else process.env.CLAUDE_PROJECT_DIR = originalProject;
    rmSync(parent, { recursive: true, force: true });
    delete process.env.ORK_NO_STALE_SWEEP;
  });

  it('isEmptyOfFiles: returns true for an empty dir', () => {
    const d = join(parent, 'empty');
    mkdirSync(d);
    expect(isEmptyOfFiles(d)).toBe(true);
  });

  it('isEmptyOfFiles: returns true for nested empty dirs only', () => {
    const d = join(parent, 'nested-empty');
    mkdirSync(join(d, 'apps', 'web'), { recursive: true });
    expect(isEmptyOfFiles(d)).toBe(true);
  });

  it('isEmptyOfFiles: returns false when ANY file is present', () => {
    const d = join(parent, 'has-file');
    mkdirSync(join(d, 'src'), { recursive: true });
    writeFileSync(join(d, 'src', 'x.ts'), 'export {};');
    expect(isEmptyOfFiles(d)).toBe(false);
  });

  it('isEmptyOfFiles: returns false past MAX_DEPTH_FILES (conservative)', () => {
    // Regression for the self-review finding: the depth bailout originally
    // returned true (would falsely flag deeply-nested trees as empty). The
    // conservative answer when we can't verify is false (treat as non-empty).
    const d = join(parent, 'deep-tree');
    // Build a 5-level deep chain — past MAX_DEPTH_FILES=3.
    let cursor = d;
    for (let i = 0; i < 5; i++) {
      cursor = join(cursor, `l${i}`);
    }
    mkdirSync(cursor, { recursive: true });
    // Top 3 levels look empty, but we can't verify past depth — must say false.
    expect(isEmptyOfFiles(d)).toBe(false);
  });

  it('isEmptyOfFiles: ignores .DS_Store / Thumbs.db cruft (Finder metadata)', () => {
    // macOS Finder leaves .DS_Store everywhere; an aborted worktree that
    // happened to be opened in Finder would otherwise be flagged non-empty.
    const d = join(parent, 'mac-cruft');
    mkdirSync(d);
    writeFileSync(join(d, '.DS_Store'), 'macos junk');
    expect(isEmptyOfFiles(d)).toBe(true);

    writeFileSync(join(d, 'Thumbs.db'), 'windows junk');
    expect(isEmptyOfFiles(d)).toBe(true);
  });

  it('LEAVES a stale empty sibling <repo>-* alone (#3319 layout retired, #3353)', () => {
    // The original #1884 reaper walked the parent directory for this shape.
    // That branch is gone: the hook must not touch anything outside the
    // project directory, so this sibling survives even though it satisfies
    // every deletion predicate the old branch had.
    const sibling = join(parent, 'fakerepo-aborted');
    mkdirSync(join(sibling, 'apps'), { recursive: true });
    backdate(sibling, MIN_AGE_MS + 60_000);

    sweepStaleWorktrees({} as any, NOOP_CTX);

    expect(existsSync(sibling)).toBe(true);
  });

  it('skips the .worktrees sweep when git worktree list fails (null registry → fail-closed)', () => {
    // A project that is NOT a git repo: `git -C project worktree list` fails,
    // registeredWorktrees returns null, and the sweep MUST skip rather than
    // fall through to the emptiness + mtime predicates.
    const nogitParent = mkdtempSync(join(tmpdir(), 'sweep-nogit-'));
    const nogitProject = join(nogitParent, 'norepo');
    const shell = join(nogitProject, '.worktrees', 'agent-stale');
    mkdirSync(join(shell, 'children'), { recursive: true });
    backdate(shell, MIN_AGE_MS + 60_000);

    try {
      const removed = sweepWorktreeShells(nogitProject, NOOP_CTX);
      expect(removed).toBe(0);
      expect(existsSync(shell)).toBe(true);
    } finally {
      rmSync(nogitParent, { recursive: true, force: true });
    }
  });

  it('opt-out via ORK_NO_STALE_SWEEP=1 short-circuits the hook', () => {
    const shell = join(project, '.worktrees', 'agent-stale');
    mkdirSync(join(shell, 'children'), { recursive: true });
    backdate(shell, MIN_AGE_MS + 60_000);

    process.env.ORK_NO_STALE_SWEEP = '1';
    sweepStaleWorktrees({} as any, NOOP_CTX);

    expect(existsSync(shell)).toBe(true);
  });

  it('the hook entry point removes a stale orphan shell end to end', () => {
    const shell = join(project, '.worktrees', 'agent-stale');
    mkdirSync(join(shell, 'children'), { recursive: true });
    writeFileSync(join(shell, 'children', '.gitkeep'), '');
    backdate(shell, MIN_AGE_MS + 60_000);

    const res = sweepStaleWorktrees({} as any, NOOP_CTX);

    expect(res.continue).toBe(true);
    expect(existsSync(shell)).toBe(false);
  });
});

describe('sweepWorktreeShells + sweepPendingMarkers (#2335)', () => {
  let parent: string;
  let project: string;

  // Make the fake project a git repo WITH a commit so `git worktree add`
  // works for the registered-worktree cases.
  beforeEach(() => {
    parent = mkdtempSync(join(tmpdir(), 'sweep-2336-'));
    project = join(parent, 'fakerepo');
    mkdirSync(project, { recursive: true });
    execFileSync('git', ['init', '--quiet', project], { stdio: 'ignore' });
    writeFileSync(join(project, 'README.md'), 'x');
    const gitc = (...args: string[]) =>
      execFileSync('git', ['-C', project, '-c', 'user.email=t@t', '-c', 'user.name=t', ...args], {
        stdio: 'ignore',
      });
    gitc('add', '.');
    gitc('commit', '--quiet', '-m', 'init', '--no-gpg-sign');
  });

  afterEach(() => {
    rmSync(parent, { recursive: true, force: true });
  });

  it('isEmptyOfFiles: ignores .gitkeep placeholders (pre-#2335 orphan shells)', () => {
    const d = join(parent, 'shell');
    mkdirSync(join(d, 'children'), { recursive: true });
    writeFileSync(join(d, 'children', '.gitkeep'), '');
    expect(isEmptyOfFiles(d)).toBe(true);
  });

  it('removes a stale orphan agent-* shell inside .worktrees/', () => {
    const shell = join(project, '.worktrees', 'agent-abc123');
    mkdirSync(join(shell, 'children'), { recursive: true });
    writeFileSync(join(shell, 'children', '.gitkeep'), '');
    backdate(shell, MIN_AGE_MS + 60_000);

    const removed = sweepWorktreeShells(project, NOOP_CTX);
    expect(removed).toBe(1);
    expect(existsSync(shell)).toBe(false);
  });

  it('SKIPS a fresh shell under the 1-hour threshold (race protection)', () => {
    const shell = join(project, '.worktrees', 'agent-fresh');
    mkdirSync(join(shell, 'children'), { recursive: true });

    const removed = sweepWorktreeShells(project, NOOP_CTX);
    expect(removed).toBe(0);
    expect(existsSync(shell)).toBe(true);
  });

  it('SKIPS a registered worktree inside .worktrees/', () => {
    const wt = join(project, '.worktrees', 'real-task');
    execFileSync('git', ['-C', project, 'worktree', 'add', '--detach', wt], { stdio: 'ignore' });
    backdate(wt, MIN_AGE_MS + 60_000);

    const removed = sweepWorktreeShells(project, NOOP_CTX);
    expect(removed).toBe(0);
    expect(existsSync(wt)).toBe(true);
  });

  it('SKIPS a shell containing real files', () => {
    const shell = join(project, '.worktrees', 'agent-with-work');
    mkdirSync(shell, { recursive: true });
    writeFileSync(join(shell, 'notes.md'), 'unsaved work');
    backdate(shell, MIN_AGE_MS + 60_000);

    const removed = sweepWorktreeShells(project, NOOP_CTX);
    expect(removed).toBe(0);
    expect(existsSync(shell)).toBe(true);
  });

  function writeMarker(name: string, worktreePath: string | null): string {
    const dir = join(project, '.claude', 'state', 'worktree-pending');
    mkdirSync(dir, { recursive: true });
    const p = join(dir, `${name}.json`);
    writeFileSync(
      p,
      worktreePath === null
        ? 'not json {'
        : JSON.stringify({ parent_sid: 's1', worktree_path: worktreePath, name }),
    );
    return p;
  }

  it('removes a stale marker whose worktree never materialized', () => {
    const p = writeMarker('agent-dead', join(project, '.worktrees', 'agent-dead'));
    backdate(p, MIN_AGE_MS + 60_000);

    const removed = sweepPendingMarkers(project, NOOP_CTX);
    expect(removed).toBe(1);
    expect(existsSync(p)).toBe(false);
  });

  it('removes a stale unparseable marker', () => {
    const p = writeMarker('agent-corrupt', null);
    backdate(p, MIN_AGE_MS + 60_000);

    const removed = sweepPendingMarkers(project, NOOP_CTX);
    expect(removed).toBe(1);
    expect(existsSync(p)).toBe(false);
  });

  it('KEEPS a marker pointing at a registered worktree', () => {
    const wt = join(project, '.worktrees', 'live-task');
    execFileSync('git', ['-C', project, 'worktree', 'add', '--detach', wt], { stdio: 'ignore' });
    const p = writeMarker('live-task', wt);
    backdate(p, MIN_AGE_MS + 60_000);

    const removed = sweepPendingMarkers(project, NOOP_CTX);
    expect(removed).toBe(0);
    expect(existsSync(p)).toBe(true);
  });

  it('KEEPS a fresh marker (race protection)', () => {
    const p = writeMarker('agent-justnow', join(project, '.worktrees', 'agent-justnow'));

    const removed = sweepPendingMarkers(project, NOOP_CTX);
    expect(removed).toBe(0);
    expect(existsSync(p)).toBe(true);
  });
});
